CREATE TABLE quote_lines(id TEXT PRIMARY KEY,quote_id TEXT NOT NULL REFERENCES quotes(id),position INTEGER NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),net_minor INTEGER NOT NULL CHECK(net_minor>=0),vat_minor INTEGER NOT NULL CHECK(vat_minor>=0),snapshot_json TEXT NOT NULL,UNIQUE(quote_id,position));
CREATE TABLE payment_evidence(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),paid_at TEXT NOT NULL,method TEXT NOT NULL,reference TEXT NOT NULL,registered_by TEXT NOT NULL REFERENCES users(id),registered_at TEXT NOT NULL);
